    function ( $markup ) {
        $post_id = get_the_ID();
        if ( ! $post_id ) {
            return $markup;
        }
        $author_id = (int) get_post_field( 'post_author', $post_id );
        $author = $author_id > 0 ? get_userdata( $author_id ) : false;
