add_filter(
	'the_content',
	function ( $content ) {
		if ( is_admin() || ! is_singular() || ! is_string( $content ) ) {
			return $content;
		}

		$current_url = rawurldecode( (string) get_permalink() );
		if ( preg_match( '/(?:visa|تأشيرة|تاشيرة|التاشيره|فيزا)/iu', $current_url ) ) {
			return $content;
		}

		return preg_replace_callback(
			'#<section\b[^>]*>.*?<h3\b[^>]*>\s*روابط مفيدة قد تهمّك\s*</h3>.*?</section>#uis',
			function ( $match ) {
				return preg_replace(
					'#<li\b[^>]*>\s*<a\b[^>]*>[^<]*(?:visa|تأشيرة|تاشيرة|التاشيره|فيزا)[^<]*</a>\s*</li>#uis',
					'',
					$match[0]
				);
			},
			$content
		);
	},
	PHP_INT_MAX
);

/**
 * One-time repair for two crossed Kazakhstan Polylang translation pairs.
 * Exact IDs and languages are guarded before any relationship is changed.
 */
add_action('init', function () {
    $flag = 'arcadia_kz_translation_pairs_20260825_v3';
    if (get_option($flag) || !function_exists('pll_save_post_translations') || !function_exists('pll_get_post_language')) {
        return;
    }

    $expected = array(
        568  => 'ar', // Arabic Kazakhstan cities
        2549 => 'en', // English Kazakhstan cities
        755  => 'ar', // Arabic Kazakhstan overview
        2586 => 'en', // English Kazakhstan overview
    );

    foreach ($expected as $post_id => $language) {
        if (get_post_type($post_id) !== 'page' || pll_get_post_language($post_id, 'slug') !== $language) {
            return;
        }
    }

    // Save the overview pair first because it was crossed with the cities
    // group. Re-save the cities pair last so both directions are rebuilt.
    pll_save_post_translations(array('ar' => 755, 'en' => 2586));
    pll_save_post_translations(array('ar' => 568, 'en' => 2549));

    // The legacy cities group was corrupted asymmetrically: the Arabic page
    // knew the English page, but not vice versa. Explicitly repair the English
    // source only if the public API still leaves its Arabic key missing.
    $english_cities = pll_get_post_translations(2549);
    if (
        empty($english_cities['ar'])
        && function_exists('PLL')
        && isset(PLL()->model->post)
        && method_exists(PLL()->model->post, 'save_translations')
    ) {
        PLL()->model->post->save_translations(2549, array('ar' => 568, 'en' => 2549));
    }
    update_option($flag, gmdate('c'), false);
}, 100);

