    register_rest_route('arcadia/v1', '/kz-translation-audit', array(
        'methods'             => 'GET',
        'permission_callback' => '__return_true',
        'callback'            => function () {
            $rows = array();
            foreach (array(568, 2549, 755, 2586) as $post_id) {
                $rows[$post_id] = array(
                    'language'     => function_exists('pll_get_post_language') ? pll_get_post_language($post_id, 'slug') : null,
                    'translations' => function_exists('pll_get_post_translations') ? pll_get_post_translations($post_id) : array(),
                );
            }
            return rest_ensure_response($rows);
        },
    ));
});

