/**
 * Localize global template output on English frontend URLs only.
 * - Keep the global FAQPage schema in the current page language.
 * - Correct Yoast website, organization and breadcrumb labels.
 * - Translate the floating contact hub and its WhatsApp intent.
 */
function arcadia_is_english_frontend_request() {
    if (is_admin()) {
        return false;
    }
    if (function_exists('pll_current_language') && pll_current_language('slug') === 'en') {
        return true;
    }
    $path = wp_parse_url(isset($_SERVER['REQUEST_URI']) ? wp_unslash($_SERVER['REQUEST_URI']) : '/', PHP_URL_PATH);
    return $path === '/en' || strpos((string) $path, '/en/') === 0;
}

