function arcadia_localize_global_faq_schema($html) {
    return preg_replace_callback(
        '#<script type="application/ld\\+json">\\s*(\\{[^<]*"@type"\\s*:\\s*"FAQPage"[^<]*\\})\\s*</script>#su',
        function ($match) {
            $data = json_decode($match[1], true);
            if (!is_array($data) || empty($data['mainEntity']) || !is_array($data['mainEntity'])) {
                return $match[0];
            }

            $names = array();
            foreach ($data['mainEntity'] as $entity) {
                $names[] = isset($entity['name']) ? (string) $entity['name'] : '';
            }
            $joined = implode(' | ', $names);
            // Touch only Arcadia's bilingual global FAQ block, never a page FAQ.
            if (
                strpos($joined, 'What countries does Arcadia Tourism operate in?') === false
                || strpos($joined, 'ما هي الدول التي تعمل فيها شركة أركاديا السياحية؟') === false
            ) {
                return $match[0];
            }

            $english = arcadia_is_english_frontend_request();
            $filtered = array_values(array_filter($data['mainEntity'], function ($entity) use ($english) {
                $name = isset($entity['name']) ? (string) $entity['name'] : '';
