function arcadia_localize_english_floating_hub($html, $current_slug = '') {
    if (!arcadia_is_english_frontend_request()) {
        return $html;
    }

    $replacements = array(
        'تحدث مع ليلى — مساعدتك الذكية 🤖' => 'Chat with Laila — your smart travel assistant 🤖',
        'تواصل عبر واتساب 💚'             => 'Chat on WhatsApp 💚',
        '>تواصل معنا<'                    => '>Contact us<',
        "'تواصل معنا'"                   => "'Contact us'",
        "'إغلاق'"                        => "'Close'",
        "'إعلاق'"                        => "'Close'",
    );
    $html = strtr($html, $replacements);
    $html = str_replace('alt="شركة أركاديا السياحية"', 'alt="Arcadia Tourism Company"', $html);

    $path = wp_parse_url(isset($_SERVER['REQUEST_URI']) ? wp_unslash($_SERVER['REQUEST_URI']) : '/', PHP_URL_PATH);
    $is_china = strpos($current_slug, 'china-') === 0
        || strpos($current_slug, 'sourcing-') === 0
        || $current_slug === 'import-from-china'
        || strpos((string) $path, '/en/china-') === 0
        || strpos((string) $path, '/en/sourcing-') === 0;
    $phone = $is_china ? '8618923166757' : '77064007561';
    $message = $is_china
        ? 'Hello Arcadia, I would like to ask about tourism and travel services in China.'
        : 'Hello Arcadia, I would like to ask about a tour package.';
    $href = 'https://wa.me/' . $phone . '?text=' . rawurlencode($message);
    $general_href = 'https://wa.me/77064007561?text=' . rawurlencode('Hello Arcadia, I would like to ask about a tour package.');
    $china_href = 'https://wa.me/8618923166757?text=' . rawurlencode('Hello Arcadia, I would like to ask about tourism and travel services in China.');

    // Legacy footer scripts rewrite the href after page load. Replace their
    // Arabic encoded values too, so the live DOM remains English.
    $html = preg_replace(
        '#https://wa\\.me/77064007561\\?text=%D9[^\'"<\\s;]+#u',
        esc_url_raw($general_href),
        $html
    );
    $html = preg_replace(
        '#https://wa\\.me/8618923166757\\?text=%D9[^\'"<\\s;]+#u',
        esc_url_raw($china_href),
        $html
    );
    $html = preg_replace(
        '#(<a\\s+class="arcadia-hub-item"\\s+id="arcWa"\\s+href=")[^"]*(")#u',
        '$1' . esc_url($href) . '$2',
        $html,
        1
    );

    $client_guard = '<script>(function(){'
        . 'var general=' . wp_json_encode($general_href) . ',china=' . wp_json_encode($china_href) . ';'
        . 'function fixArcadiaEnglishWa(){var a=document.getElementById("arcWa");if(!a)return;'
        . 'var p=location.pathname||"";var isChina=/^\\/en\\/(?:china-|sourcing-)/.test(p)||p.indexOf("/en/import-from-china")===0;'
        . 'var wanted=isChina?china:general;if(a.href!==wanted)a.href=wanted;}'
        . 'if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",fixArcadiaEnglishWa);else fixArcadiaEnglishWa();'
        . 'setTimeout(fixArcadiaEnglishWa,500);setTimeout(fixArcadiaEnglishWa,1800);setTimeout(fixArcadiaEnglishWa,4200);'
        . '})();</script>';
    $html = str_replace('</body>', $client_guard . '</body>', $html);
    return $html;
}

