/**
 * Remove theme/builder Google Font bundles after every component has enqueued
 * its styles. The live site used Tajawal, but still downloaded every weight and
 * italic of Roboto and Roboto Slab. Arabic pages get one intentional Tajawal
 * request; English pages use the system stack and need no webfont request.
 */
add_action(
	'wp_enqueue_scripts',
	static function () {
		global $wp_styles;

		if ( $wp_styles instanceof WP_Styles ) {
			foreach ( (array) $wp_styles->queue as $handle ) {
				$registered = $wp_styles->registered[ $handle ] ?? null;
				$source     = $registered ? (string) $registered->src : '';
				if ( false !== stripos( $source, 'fonts.googleapis.com' ) || false !== stripos( $source, 'fonts.gstatic.com' ) ) {
					wp_dequeue_style( $handle );
					wp_deregister_style( $handle );
				}
			}
		}

		$is_arabic = function_exists( 'pll_current_language' )
			? 'ar' === pll_current_language( 'slug' )
			: 0 === strpos( get_locale(), 'ar' );

		if ( $is_arabic ) {
			wp_enqueue_style(
				'arcadia-tajawal-font',
				'https://fonts.googleapis.com/css2?family=Tajawal:wght@300;400;500;700;900&display=swap',
				array(),
				null
			);
		}
	},
	PHP_INT_MAX
);

// LiteSpeed's async-font optimizer runs after the WordPress style queue. Trim
// its generated WebFontConfig at the documented final-buffer hook as well.
add_filter(
	'litespeed_buffer_after',
	static function ( $html ) {
		if ( false === stripos( $html, 'WebFontConfig' ) ) return $html;

		$is_arabic = function_exists( 'pll_current_language' )
			? 'ar' === pll_current_language( 'slug' )
			: 0 === strpos( get_locale(), 'ar' );

		if ( $is_arabic ) {
			$html = preg_replace(
				'/WebFontConfig\s*=\s*\{google:\{families:\[[^\]]*\]\}\}/i',
				'WebFontConfig={google:{families:["Tajawal:wght@300;400;500;700;900&display=swap"]}}',
				$html,
				1
			);

			return $html;
		}

		// English uses the system stack, so neither the config nor its loader is needed.
		$html = preg_replace( '/<script[^>]*>\s*WebFontConfig[\s\S]*?<\/script>/i', '', $html, 1 );
		return preg_replace( '/<script[^>]+webfontloader\.min\.js[^>]*><\/script>/i', '', $html, 1 );
	},
	PHP_INT_MAX
);

