		  var selector = 'a[href^="tel:"],a[href*="wa.me/"],.arcadia-phone,.phone,.telephone,[class*="phone-number"],[class*="whatsapp-btn"]';
		  var numberPattern = /(?:\+|00)?[0-9\u0660-\u0669](?:[\s().-]*[0-9\u0660-\u0669]){6,}/g;

		  function isolateNumbers(root) {
		    var targets = root.matches && root.matches(selector) ? [root] : Array.prototype.slice.call(root.querySelectorAll ? root.querySelectorAll(selector) : []);
