		      if (target.dataset.arcadiaBidiReady === '1') return;
		      var walker = document.createTreeWalker(target, NodeFilter.SHOW_TEXT);
		      var nodes = [];
		      var node;
		      while ((node = walker.nextNode())) {
		        if (node.parentElement && node.parentElement.closest('.arcadia-phone-ltr')) continue;
		        numberPattern.lastIndex = 0;
		        if (numberPattern.test(node.nodeValue)) nodes.push(node);
		      }

		      nodes.forEach(function (textNode) {
		        var text = textNode.nodeValue;
		        var fragment = document.createDocumentFragment();
		        var lastIndex = 0;
		        numberPattern.lastIndex = 0;
		        text.replace(numberPattern, function (match, offset) {
		          fragment.appendChild(document.createTextNode(text.slice(lastIndex, offset)));
		          var bdi = document.createElement('bdi');
		          bdi.className = 'arcadia-phone-ltr';
		          bdi.dir = 'ltr';
		          bdi.textContent = match;
		          fragment.appendChild(bdi);
		          lastIndex = offset + match.length;
		          return match;
		        });
		        fragment.appendChild(document.createTextNode(text.slice(lastIndex)));
		        textNode.parentNode.replaceChild(fragment, textNode);
		      });
		      target.dataset.arcadiaBidiReady = '1';
