		<script id="arcadia-contact-conversion-tracking" data-no-optimize="1">
		(function () {
		  'use strict';
		  if (window.__arcadiaContactTrackingReady) return;
		  window.__arcadiaContactTrackingReady = true;
		  document.documentElement.setAttribute('data-arcadia-contact-tracking', 'ready');

		  var lastKey = '';
		  var lastAt = 0;

		  function methodFor(link) {
		    var href = (link.getAttribute('href') || '').toLowerCase();
		    if (href.indexOf('wa.me/') !== -1 || href.indexOf('api.whatsapp.com/') !== -1 || href.indexOf('whatsapp://') === 0) return 'whatsapp';
		    if (href.indexOf('tel:') === 0) return 'phone';
		    if (href.indexOf('mailto:') === 0) return 'email';
		    return '';
		  }

		  function placementFor(link) {
		    if (link.closest('#arcHub,.arcadia-contact-hub,[class*="floating"],[class*="sticky"]')) return 'floating_contact';
		    if (link.closest('header,.site-header')) return 'header';
		    if (link.closest('.hero,.arc-hero,[class*="hero"]')) return 'hero';
		    if (link.closest('.contact-box,.arc-cta,[class*="contact-section"],#contact')) return 'contact_section';
		    if (link.closest('footer,.site-footer')) return 'footer';
		    if (link.closest('article,.entry-content,.post-content')) return 'content';
		    return 'other';
		  }

		  document.addEventListener('click', function (event) {
		    var link = event.target && event.target.closest ? event.target.closest('a[href]') : null;
		    if (!link) return;
		    var method = methodFor(link);
		    if (!method) return;

		    var placement = placementFor(link);
		    var key = method + '|' + placement + '|' + window.location.pathname;
		    var now = Date.now();
		    if (key === lastKey && now - lastAt < 1000) return;
		    lastKey = key;
		    lastAt = now;

