function arcadia_seo_is_noindex_target( $post_id = 0 ) {
	$post_id = $post_id ? (int) $post_id : (int) get_queried_object_id();
	if ( ! $post_id ) {
		return false;
	}
	if ( in_array( $post_id, arcadia_seo_noindex_page_ids(), true ) ) {
		return true;
	}
	if ( in_array( $post_id, arcadia_seo_noindex_post_ids(), true ) ) {
		return true;
	}
	$slug = get_post_field( 'post_name', $post_id );
	return is_string( $slug ) && 0 === strpos( $slug, 'old-post-' );
}

