	if ( ! is_single() ) {
		return null;
	}
	$slug = get_post_field( 'post_name', get_queried_object_id() );
	$all  = arcadia_blog_seo_slug_configs();
	return isset( $all[ $slug ] ) ? $all[ $slug ] : null;
}

function arcadia_blog_extract_faqs_from_content( $content ) {
	$faqs = array();
	if ( ! preg_match_all( '/<h3[^>]*>(.*?)<\/h3>\s*<p[^>]*>(.*?)<\/p>/is', $content, $matches, PREG_SET_ORDER ) ) {
		return $faqs;
	}
	foreach ( $matches as $match ) {
		$q = wp_strip_all_tags( $match[1] );
		$a = wp_strip_all_tags( $match[2] );
		if ( $q && $a && ( false !== mb_strpos( $q, '؟' ) || false !== mb_strpos( $q, '?' ) ) ) {
			$faqs[] = array( 'q' => $q, 'a' => $a );
		}
		if ( count( $faqs ) >= 5 ) {
			break;
		}
	}
	return $faqs;
}

