function arcadia_alt_from_filename( $filename ) {
	$base = strtolower( pathinfo( $filename, PATHINFO_FILENAME ) );
	$rules = array(
		'russia'      => 'السياحة في روسيا — أركاديا السياحية',
		'poland'      => 'السياحة في بولندا — أركاديا السياحية',
