		'almaty'      => 'أفضل الأوقات لزيارة ألماتي — أركاديا',
		'moscow'      => 'دليل موسكو وأفضل وقت للزيارة — أركاديا',
		'china'       => 'السياحة في الصين — أركاديا السياحية',
		'family'      => 'رحلة عائلية مع أركاديا السياحية',
		'infographic' => 'إنفوجرافيك سياحي — أركاديا',
		'arcadia'     => 'أركاديا السياحية — رحلات عائلية',
	);
	foreach ( $rules as $needle => $alt ) {
		if ( false !== strpos( $base, $needle ) ) {
			return $alt;
		}
	}
	return '';
}

function arcadia_alt_resolve( $attachment_id, $src = '' ) {
	$map = arcadia_alt_id_map();
	if ( $attachment_id && isset( $map[ (int) $attachment_id ] ) ) {
		return $map[ (int) $attachment_id ];
	}
	if ( $attachment_id ) {
		$stored = get_post_meta( (int) $attachment_id, '_wp_attachment_image_alt', true );
		if ( is_string( $stored ) && trim( $stored ) !== '' ) {
			return trim( $stored );
		}
	}
	if ( $src ) {
		$filename = wp_basename( parse_url( $src, PHP_URL_PATH ) );
		$guess    = arcadia_alt_from_filename( $filename );
		if ( $guess ) {
			return $guess;
		}
	}
	return '';
}

