				}
				$src = '';
				if ( preg_match( '/\bsrc\s*=\s*([\'"])(.*?)\1/i', $tag, $sm ) ) {
					$src = $sm[2];
				}
				$attachment_id = 0;
				if ( preg_match( '/\bclass\s*=\s*([\'"])(.*?)\1/i', $tag, $cm ) && preg_match( '/wp-image-(\d+)/', $cm[2], $im ) ) {
					$attachment_id = (int) $im[1];
				}
				$alt = arcadia_alt_resolve( $attachment_id, $src );
				if ( ! $alt ) {
					return $tag;
				}
				return str_replace( '<img', '<img alt="' . esc_attr( $alt ) . '"', $tag );
			},
			$content
		);
	},
	25
);
